// SBD-6 (v1): Vercel deploy config — the failures these guard against only show up at deploy time.
// Grounded in vercel/vercel@c628be7: a `build` script adds a static-site step that needs a non-empty output
// directory (static-build STATIC_BUILD_NO_OUT_DIR / _EMPTY_OUT_DIR); a `functions` pattern that matches no file
// fails the deploy (fs-detectors detect-builders); an api/ function is packaged by @vercel/node, which runs only
// `vercel-build` (not `build`) before tracing, so data/gen must be generated by `vercel-build`.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readdirSync, readFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const vercel = JSON.parse(readFileSync(new URL('vercel.json', root), 'utf8')) as {
  buildCommand?: string;
  outputDirectory?: string;
  functions?: Record<string, { includeFiles?: string }>;
};
const pkg = JSON.parse(readFileSync(new URL('package.json', root), 'utf8')) as { scripts: Record<string, string> };

test('the static output directory exists and is not empty', () => {
  assert.equal(vercel.outputDirectory, 'public');
  assert.ok(readdirSync(new URL('public/', root)).length > 0);
});

test('every functions entry names a file that exists', () => {
  const entries = Object.keys(vercel.functions ?? {});
  assert.deepEqual(entries, ['api/interactions.ts']);
  for (const f of entries) assert.ok(existsSync(new URL(f, root)), f);
});

test('the function ships data/gen, and vercel-build generates it before the function is packaged', () => {
  assert.equal(vercel.functions?.['api/interactions.ts']?.includeFiles, 'data/gen/**');
  assert.equal(pkg.scripts['vercel-build'], 'npm run build');
  assert.equal(pkg.scripts.build, 'node scripts/build-data.ts');
  assert.equal(vercel.buildCommand, 'npm run build');
});
